import {reportDate,reportStatusAm,reportErrorAm,teacherOutcomeLabel,reportFields,bindReportFields,reportPageUrl,readReport} from './report-form.mjs';
import{meetingStatusLabel}from'./meeting-status.mjs';
import{reminderEmails}from'./announcements-due.mjs';
import{matchTeacher}from'./teacher-match.mjs';
import{LEGACY_PROGRAM,programOf,topicKey,parseProgramCsv,validateProgram,programTemplate}from'./programs.mjs';
import {dubaiDate,prettyDate,message,phoneList,waUrl,normalizeMeetingEdit} from './core.mjs';
import {validateReport,monthlyReport,reportCsv,dateRange} from './reporting.mjs';
import {parseTeacherImport} from './teacher-import.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=async text=>{await navigator.clipboard.writeText(text)};
const field=(label,name,value='',type='text',required=false)=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
const area=(label,name,value='',required=false)=>`<label class="field">${label}<textarea name="${name}" rows="3" maxlength="6000" ${required?'required':''}>${esc(value)}</textarea></label>`;

export function createWorkspace(bridge){
 let apiBase='',openAccess=false,user=null,auth=null,records=[],teachers=[],reports=[],programs=[],reminderSettings={recipients:[],enabled:false,revision:0},etag='',mode='local',syncError='',pending=null,timer,chain=Promise.resolve(),polling=false,syncing=false;
 const localKey='gubae-private-workspace-v2';let local={teachers:[],reports:[],assignments:{},teacherSent:{},meetings:[],programs:[]};try{local={...local,...JSON.parse(localStorage.getItem(localKey)||'{}')}}catch{}
 let month=bridge.program(),custom=false,from='',to='';
 const cloud=()=>mode==='cloud';
 const notice=text=>{$('#syncText').textContent=text;$('.local-note').textContent=text};
 const error=e=>{bridge.toast(e.message||'Could not complete this action.')};
 const persistLocal=()=>{localStorage.setItem(localKey,JSON.stringify(local))};
 function currentTeachers(){return cloud()?teachers:local.teachers}
 function currentReports(){return cloud()?reports:local.reports}
 function assignment(id){return cloud()?records.find(m=>m.id===id)?.teacherId:local.assignments[id]}
 async function request(path,method='GET',body,headers={}){if(!openAccess&&!user)throw Error('Sign in to use the shared workspace.');const response=await fetch(apiBase+path,{method,headers:{...(!openAccess&&user?{Authorization:'Bearer '+await user.getIdToken()}:{}),...(body?{'Content-Type':'application/json'}:{}),...headers},body:body?JSON.stringify(body):undefined});if(response.status===304)return null;const data=response.status===204?null:await response.json();if(!response.ok)throw Object.assign(Error(data?.error||'The server could not complete the request.'),{status:response.status});return{data,tag:response.headers.get('ETag')}}
 function applyRecords(){bridge.setBase(records);const next={recipients:{},sent:{},meetingEdits:{}};for(const m of records){next.recipients[m.id]=m.recipient||'';next.meetingEdits[m.id]=normalizeMeetingEdit(m,m);for(const kind of ['poster','link'])if(m.sent?.[kind])next.sent[m.id+':'+kind]=m.sent[kind]}bridge.setState(next);ensureProgram();bridge.render()}
 async function pull(force=false){if(!cloud()||pending||polling||syncing||(!force&&(document.querySelector('dialog[open]')||document.activeElement?.matches('input,textarea,select'))))return;polling=true;try{const result=await request('/api/state','GET',null,!force&&etag?{'If-None-Match':etag}:{});if(result){records=result.data.meetings;teachers=result.data.teachers;reports=result.data.reports;programs=result.data.programs||[];reminderSettings=result.data.reminderSettings||{recipients:[],enabled:false,revision:0};etag=result.tag;applyRecords()}notice(openAccess?'Open workspace · synced':'Cloud synced · '+user.email)}catch(e){notice('Sync unavailable · changes need attention');error(e)}finally{polling=false}}
 function accept(record){records=records.map(m=>m.id===record.id?record:m);etag=''}
 async function syncSnapshot(snapshot){for(let m of [...records]){const desired=normalizeMeetingEdit(m,snapshot.meetingEdits[m.id]||bridge.base().find(b=>b.id===m.id));const patch={};if(JSON.stringify(desired)!==JSON.stringify(normalizeMeetingEdit(m,m)))patch.details=desired;if((snapshot.recipients[m.id]||'')!==(m.recipient||''))patch.recipient=snapshot.recipients[m.id]||'';if(Object.keys(patch).length){const r=await request('/api/meetings/'+m.id,'PATCH',{revision:m.revision,...patch});m=r.data;accept(m)}for(const kind of ['poster','link']){const wanted=!!snapshot.sent[m.id+':'+kind];if(wanted!==!!m.sent?.[kind]){const r=await request(`/api/meetings/${m.id}/status/${kind}`,'PUT',{revision:m.revision,sent:wanted});m=r.data;accept(m)}}}}
 async function flush(){clearTimeout(timer);await chain;if(!pending)return;if(syncError)throw Error(syncError);const snapshot=pending;pending=null;notice('Saving to cloud…');syncing=true;chain=syncSnapshot(snapshot);try{await chain;syncing=false;notice(pending?'Saving to cloud…':(openAccess?'Open workspace · synced':'Cloud synced · '+user.email));if(pending)return flush()}catch(e){syncing=false;pending=structuredClone(bridge.state());syncError=e.status===409?'Another device changed this record. Discard this device’s pending edits, refresh, and apply your change again.':'Cloud save was not confirmed. Your pending changes remain open on this device. Retry before closing.';notice(syncError);chain=Promise.resolve();throw Error(syncError)}}
 const persist=state=>{if(!cloud())return false;pending=structuredClone(state);syncError='';notice('Unsynced changes · saving…');clearTimeout(timer);timer=setTimeout(()=>flush().catch(error),650);return true};
 async function mutate(path,method,body){await flush();const r=await request(path,method,body);await pull(true);return r?.data}
 async function action(run){try{await run()}catch(e){error(e)}}
 function renderGate(){return`<div class="notice">${cloud()?(openAccess?'Open shared workspace · anyone can view and edit':'Shared workspace · signed in as '+esc(user.email)):'On this device. Connect the backend in Setup and sign in to share data across mobile and PC.'}</div>`}
 function availablePrograms(){const metadata=cloud()?programs:local.programs;return [...new Set([...bridge.base().map(programOf),...metadata.map(p=>p.id)])].sort().reverse().map(id=>({id,label:metadata.find(p=>p.id===id)?.label||(id===LEGACY_PROGRAM?'October 2026 · original program':id)}));}
 function ensureProgram(){const options=availablePrograms();if(options.length&&!options.some(p=>p.id===bridge.program())){const chosen=options.find(p=>p.id===dubaiDate().slice(0,7))||options[0];month=chosen.id;custom=false;bridge.selectProgram(chosen.id);}}
 function loadLocalPrograms(ensure=true){bridge.setBase([...bridge.bundled().filter(m=>!local.deletedPrograms?.includes(programOf(m))),...local.meetings].map(m=>({...m,...local.outcomes?.[m.id]})));if(ensure)ensureProgram();}
 function drawPrograms(){const bar=$('#programBar');if(!bar)return;bar.innerHTML=`<label class="field">Monthly program<select id="activeProgram" aria-label="Monthly program">${availablePrograms().map(p=>`<option value="${esc(p.id)}" ${p.id===bridge.program()?'selected':''}>${esc(p.label)}</option>`).join('')}</select></label><button class="primary" id="newProgram">Load a new month</button><button class="secondary" id="editProgram" ${availablePrograms().length?'':'disabled'}>Edit month</button><button class="secondary" id="deleteProgram" ${availablePrograms().length?'':'disabled'}>Delete month</button><span class="muted">Earlier programs and reports stay saved.</span>${pendingTeachers().length?`<div class="notice pending-program-notice">${pendingTeachers().length} teacher assignment(s) need attention. <button class="secondary" id="reviewPendingTeachers">Review missing teachers</button></div>`:''}`;$('#activeProgram').onchange=e=>{const id=e.target.value;action(async()=>{await flush();month=id;custom=false;bridge.selectProgram(id);})};$('#newProgram').onclick=()=>programImporter();$('#editProgram').onclick=()=>manageProgram(false);$('#deleteProgram').onclick=()=>manageProgram(true);$('#reviewPendingTeachers')?.addEventListener('click',()=>bridge.navigate('teachers'));}
 function editOutcome(id){const m=bridge.meetings().find(m=>m.id===id);if(!m)return;showModal('Set meeting status',`<h2 lang="am">${esc(m.topic)}</h2><form id="meetingOutcomeForm" class="form-stack"><label class="field">Meeting status<select name="outcome">${[['auto','Based on report / scheduled time'],['held','Held'],['missed','Missed / not held'],['cancelled','Cancelled'],['postponed','Postponed']].map(([v,l])=>`<option value="${v}" ${(m.outcome||'auto')===v?'selected':''}>${l}</option>`).join('')}</select></label><div id="outcomeReasonField">${area('Why was the meeting not held?','reason',m.outcomeReason||'')}</div><p class="muted">Setting Held here does not create an attendance report. Submitting an organizer report later marks Held automatically.</p><button class="primary">Save status</button><p id="formError" role="alert"></p></form>`);const form=$('#meetingOutcomeForm'),outcome=form.querySelector('[name="outcome"]'),reason=form.querySelector('[name="reason"]');const update=()=>{const required=['missed','cancelled','postponed'].includes(outcome.value);$('#outcomeReasonField').hidden=!required;reason.disabled=!required;reason.required=required;reason.maxLength=2000;};outcome.onchange=update;update();form.onsubmit=e=>{e.preventDefault();submitForm(form,async()=>{const value=outcome.value,why=reason.value.trim();if(['missed','cancelled','postponed'].includes(value)&&(!why||why.length>2000))throw Error('Give a reason up to 2000 characters.');if(cloud())await mutate('/api/meetings/'+id+'/outcome','PUT',{revision:m.revision,outcome:value,reason:why});else{local.outcomes={...local.outcomes,[id]:{outcome:value==='auto'?null:value,outcomeReason:['held','auto'].includes(value)?'':why}};persistLocal();loadLocalPrograms();bridge.render();}$('#workspaceDialog').close();bridge.toast('Meeting status saved.');});};}
 function manageProgram(remove){const id=bridge.program(),metadata=cloud()?programs:local.programs,record=metadata.find(p=>p.id===id),label=availablePrograms().find(p=>p.id===id)?.label||id,meetings=bridge.base().filter(m=>programOf(m)===id);showModal(remove?'Delete month':'Edit month',`<form id="manageProgramForm" class="form-stack"><p><strong>${esc(label)}</strong> · ${meetings.length} meetings</p>${remove?`<p class="notice">Deleting this month permanently removes its meetings, sent confirmations, organizer reports and report links from the shared workspace. Teacher contacts and other months stay saved.</p><label class="field">Type ${esc(id)} to confirm<input name="confirm" required autocomplete="off"></label>`:`<label class="field">Month name<input name="label" value="${esc(label)}" maxlength="100" required></label><p class="muted">Program ID: ${esc(id)}. To change an individual meeting’s date, time or link, use Edit gubae on All meetings.</p>`}<button class="primary" type="submit">${remove?'Delete month permanently':'Save month'}</button><p id="manageProgramError" role="alert"></p></form>`);$('#manageProgramForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),errorBox=$('#manageProgramError'),close=$('#closeWorkspace');button.disabled=true;close.disabled=true;try{const input=e.target.querySelector(remove?'[name="confirm"]':'[name="label"]').value.trim();if(remove&&input!==id)throw Error('Type '+id+' to confirm deletion.');if(!remove&&(!input||input.length>100))throw Error('Enter a month label up to 100 characters.');if(cloud()){await mutate('/api/programs/'+id,remove?'DELETE':'PATCH',{revision:record?.revision||0,...(remove?{confirm:input}:{label:input})});}else{if(remove){const ids=new Set(meetings.map(m=>m.id));local.meetings=local.meetings.filter(m=>!ids.has(m.id));local.programs=local.programs.filter(p=>p.id!==id);local.deletedPrograms=[...new Set([...(local.deletedPrograms||[]),id])];local.reports=local.reports.filter(r=>!ids.has(r.meetingId||r.id));for(const k of ['assignments','teacherSent','outcomes'])for(const meetingId of ids)if(local[k])delete local[k][meetingId];const state=structuredClone(bridge.state());for(const meetingId of ids){delete state.recipients[meetingId];delete state.meetingEdits[meetingId];delete state.sent[meetingId+':poster'];delete state.sent[meetingId+':link'];}bridge.setState(state);bridge.save();}else{local.programs=local.programs.filter(p=>p.id!==id);local.programs.push({id,month:id,label:input});}persistLocal();loadLocalPrograms();bridge.render();}$('#workspaceDialog').close();bridge.toast(remove?'Month deleted. Other months and teacher contacts are unchanged.':'Month updated.');}catch(err){errorBox.textContent=err.message;}finally{button.disabled=false;close.disabled=false;}};}
 function programImporter(){
  const next=new Date(bridge.program()+'-01T12:00:00Z');next.setUTCMonth(next.getUTCMonth()+1);const proposed=next.toISOString().slice(0,7);
  showModal('Load a new monthly program',`<div class="form-stack"><p>Create a separate program for the next month. Previous meetings, send statuses and reports stay saved.</p><p class="notice">${cloud()?'The new program will sync across your devices.':'Sign in through Cloud setup first for cross-device saving. Otherwise this program stays on this device.'}</p><div class="editor-grid">${field('Starting Gregorian month / year','programMonth',proposed,'month',true)}${field('Program label (optional)','programLabel','','text')}</div><p class="muted">Use any label, including an Ethiopian month name. Paste your ማኅበራት / የጉባኤ ቀን / መምህር table, or upload CSV. English dates such as Oct. 15 use the starting month/year selected above. Dates may extend into the following month.</p><button class="secondary" id="programTemplate">Download template with current mahbers</button><label class="field">CSV / text file<input id="programFile" type="file" accept=".csv,.tsv,.txt,.md,text/csv,text/plain,text/markdown,text/tab-separated-values"></label><label class="field">Meeting details<textarea id="programText" rows="8" maxlength="300000" placeholder="ማኅበራት,የጉባኤ ቀን,መምህር"></textarea></label><p class="muted">Required columns: ማኅበራት and የጉባኤ ቀን (or topic and date). መምህር assigns teachers by name. Optional: link, startTime (24-hour Dubai time), durationMinutes, poster (HTTPS image URL). Missing Zoom links remain drafts until you add them. Default time is 21:00 and duration is 90 minutes. Fill the new dates and links; old posters are not reused. You can also attach a poster on this device when preparing its announcement.</p><label><input id="programCarry" type="checkbox" checked> Reuse recipient numbers for matching mahbers; reuse previous teachers only when no teacher is supplied</label><button class="primary" id="programPreview">Preview program</button><div id="programPreviewResults" aria-live="polite"></div><button class="primary" id="programSave" disabled>Save new month</button><p id="programError" role="alert"></p></div>`);
  const text=$('#programText'),file=$('#programFile'),monthInput=document.querySelector('[name="programMonth"]'),labelInput=document.querySelector('[name="programLabel"]'),carry=$('#programCarry'),preview=$('#programPreview'),save=$('#programSave'),results=$('#programPreviewResults'),errors=$('#programError'),close=$('#closeWorkspace'),dialog=$('#workspaceDialog');let reviewed=null,busy=false;
  const read=()=>validateProgram({month:monthInput.value,label:labelInput.value||monthInput.value,carryContacts:carry.checked,meetings:parseProgramCsv(text.value)});
  const invalidate=()=>{reviewed=null;save.disabled=true;results.textContent='';errors.textContent=''};for(const el of [text,monthInput,labelInput,carry])el.oninput=invalidate;
  $('#programTemplate').onclick=()=>bridge.download(new Blob([programTemplate(bridge.meetings())],{type:'text/csv;charset=utf-8'}),'gubae-month-template.csv');
  file.onchange=async()=>{invalidate();try{if(!file.files?.length)return;if(file.files[0].size>300000)throw Error('Use a file smaller than 300 KB.');text.value=await file.files[0].text()}catch(e){errors.textContent=e.message}};
  preview.onclick=()=>{invalidate();try{const p=read();if(availablePrograms().some(v=>v.id===p.id))throw Error('This month already has a program. Select it above to edit meetings.');reviewed=p;const checked=p.meetings.map(m=>({...m,match:matchTeacher(m.scheduledTeacherName,currentTeachers())}));const unresolved=[...new Map(checked.filter(m=>['missing','ambiguous'].includes(m.match.status)).map(m=>[m.scheduledTeacherName,m])).values()];results.innerHTML=`<p><strong>${p.meetings.length} meetings</strong> · ${esc(p.label)} · ${checked.filter(m=>m.match.status==='matched').length} teacher matches · ${checked.filter(m=>!m.link).length} Zoom links to add</p>${unresolved.length?`<div class="notice">${unresolved.map(m=>`<p><strong>${esc(m.scheduledTeacherName)}</strong>: ${m.match.status==='missing'?'add this teacher contact first':'multiple contacts match — choose manually'}. Other teachers will still be assigned.</p>`).join('')}</div>`:''}<div class="report-table-wrap"><table class="report-table"><thead><tr><th>Mahber</th><th>Date / Dubai time</th><th>Teacher</th><th>Zoom / poster</th></tr></thead><tbody>${checked.map(m=>`<tr><td>${esc(m.topic)}</td><td>${esc(m.date)} · ${esc(m.startTime)}</td><td>${esc(m.scheduledTeacherName||'No teacher supplied')}<small>${m.match.status==='matched'?'Matched: '+esc(m.match.name):m.match.status==='missing'?'Add this teacher first':m.match.status==='ambiguous'?'Choose the correct contact':'Previous assignment reused only if requested'}</small></td><td>${m.link?'Zoom link ready':'Draft · add Zoom link'}<small>${m.poster?'Poster URL included':'Attach a new poster'}</small></td></tr>`).join('')}</tbody></table></div>`;save.disabled=false;}catch(e){errors.textContent=e.message}};
  const cancel=e=>{if(busy)e.preventDefault()};dialog.addEventListener('cancel',cancel);dialog.addEventListener('close',()=>dialog.removeEventListener('cancel',cancel),{once:true});
  save.onclick=async()=>{if(!reviewed||busy)return;busy=true;const targetCloud=cloud();for(const el of [text,file,monthInput,labelInput,carry,preview,save,close])el.disabled=true;errors.textContent='';try{const p=read();if(targetCloud){await flush();await request('/api/programs','POST',p);const result=await request('/api/state');records=result.data.meetings;teachers=result.data.teachers;reports=result.data.reports;programs=result.data.programs||[];reminderSettings=result.data.reminderSettings||{recipients:[],enabled:false,revision:0};etag=result.tag;applyRecords();}else{if(availablePrograms().some(v=>v.id===p.id))throw Error('This month is already loaded.');const prior=bridge.base().filter(m=>programOf(m)<p.id).sort((a,b)=>b.date.localeCompare(a.date));const state=structuredClone(bridge.state());const imported=p.meetings.map((m,i)=>{const id=p.id+'-'+(i+1),old=p.carryContacts?prior.find(v=>topicKey(v.topic)===topicKey(m.topic)):null;if(old){state.recipients[id]=state.recipients[old.id]||old.recipient||'';if(!m.scheduledTeacherName)local.assignments[id]=local.assignments[old.id]||null;}if(m.scheduledTeacherName)local.assignments[id]=matchTeacher(m.scheduledTeacherName,currentTeachers()).teacherId;return{...m,id};});local.meetings.push(...imported);local.deletedPrograms=(local.deletedPrograms||[]).filter(id=>id!==p.id);local.programs.push({id:p.id,month:p.month,label:p.label});persistLocal();loadLocalPrograms();bridge.setState(state);if(!bridge.save())throw Error('Could not save all local settings. Export a backup before closing.');}month=p.month;custom=false;bridge.selectProgram(p.id);dialog.close();bridge.navigate('meetings');bridge.toast(pendingTeachers().length?'Program saved. Matched teachers assigned; review the remaining names in Teachers.':'New monthly program saved. Teachers assigned and earlier programs preserved.');}catch(e){errors.textContent=e.message+' If saving was interrupted, refresh and check the month selector before retrying.';}finally{busy=false;for(const el of [text,file,monthInput,labelInput,carry,preview,close])el.disabled=false;if(dialog.open)save.disabled=false;}}
 }
 function pendingTeachers(){return bridge.meetings().filter(m=>m.scheduledTeacherName&&!assignment(m.id)).map(m=>({...m,match:matchTeacher(m.scheduledTeacherName,currentTeachers())}));}
 async function resolveScheduleAssignments(){if(cloud()){await flush();await mutate('/api/teachers/resolve-assignments','POST',{});}else{for(const m of bridge.base().filter(m=>m.scheduledTeacherName&&!local.assignments[m.id])){const match=matchTeacher(m.scheduledTeacherName,currentTeachers());if(match.teacherId)local.assignments[m.id]=match.teacherId;}persistLocal();}}
 function pendingTeacherPanel(){const pending=pendingTeachers(),unique=[...new Map(pending.map(m=>[m.scheduledTeacherName,m])).values()];return pending.length?`<section class="pending-teachers"><h3>Teacher assignments need attention</h3><p>${pending.length} gubae(s) are waiting for a teacher match. Other assignments are already saved.</p><button class="secondary" data-resolve-scheduled>Match pending assignments</button>${unique.map(m=>`<div class="pending-teacher-row"><div><strong>${esc(m.scheduledTeacherName)}</strong><p>${m.match.status==='missing'?'Add this teacher contact first.':m.match.status==='ambiguous'?'More than one contact matches. Choose the correct teacher in the meeting below.':'A matching contact is ready. Select Match pending assignments.'}</p></div>${m.match.status==='missing'?`<button class="secondary" data-add-scheduled-teacher="${esc(m.scheduledTeacherName)}">Add this teacher</button>`:''}</div>`).join('')}</section>`:''}
 function teachersView(){return`<div class="workspace"><div class="section-top"><div><h2 class="section-title">Teachers & Zoom invitations</h2><p class="section-subtitle">${openAccess?'Shared contacts · visible to everyone.':'Private contacts.'} Teacher names stay out of announcement messages.</p></div><div class="button-row"><button class="secondary" id="importTeachers">Import teachers</button><button class="primary" id="newTeacher">Add teacher</button></div></div>${pendingTeacherPanel()}<div class="setup">${renderGate()}<div class="teacher-list">${currentTeachers().map(t=>`<article class="contact-card"><strong>${esc(t.name)}${t.archived?' · archived':''}</strong><p>${esc(t.phone)}${t.email?' · '+esc(t.email):''}</p><p>${esc(t.notes)}</p><button class="secondary" data-teacher-edit="${t.id}">Edit contact</button></article>`).join('')||'<p>No teacher contacts yet. Add a contact, then assign them to a gubae below.</p>'}</div></div>${bridge.meetings().map(m=>{const assigned=assignment(m.id),t=currentTeachers().find(t=>t.id===assigned),done=cloud()?records.find(r=>r.id===m.id)?.sent?.teacher:local.teacherSent[m.id];return`<div class="recipient-row"><div><h3 lang="am">${esc(m.topic)}</h3><small>${prettyDate(m.date)} · Dubai</small></div><div class="field"><label for="teacher-${m.id}">Assigned teacher</label><select id="teacher-${m.id}" data-assignment="${m.id}"><option value="">Unassigned</option>${currentTeachers().filter(t=>!t.archived||t.id===assigned).map(t=>`<option value="${t.id}" ${t.id===assigned?'selected':''}>${esc(t.name)}</option>`).join('')}</select>${m.scheduledTeacherName&&!t?`<span class="field-hint">Scheduled teacher: ${esc(m.scheduledTeacherName)} · assignment pending</span>`:''}${t?`${m.link?`<button class="prepare" data-teacher-send="${m.id}">Open Zoom invitation ↗</button>`:`<button class="secondary" data-edit="${m.id}">Add Zoom link first</button>`}<button class="secondary" data-teacher-status="${m.id}" ${!m.link?'disabled':''}>${done?'✓ Sent · undo':'Mark sent to teacher'}</button>`:''}</div></div>`}).join('')}</div>`}
 function teacherEditor(id,defaults={}){const t=currentTeachers().find(t=>t.id===id)||defaults;showModal(openAccess?'Shared teacher contact':'Private teacher contact',`<form id="teacherForm" class="form-stack">${field(openAccess?'Teacher name':'Teacher name (private)','name',t.name||'','text',true)}${field('WhatsApp number · include country code','phone',t.phone||'','tel',true)}${field('Email (optional)','email',t.email||'','email')}${area(openAccess?'Notes (shared)':'Notes (private)','notes',t.notes||'')}<label><input name="archived" type="checkbox" ${t.archived?'checked':''}> Archive contact</label><button class="primary">Save contact</button><p role="alert" id="formError"></p></form>`);$('#teacherForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async()=>{const data=Object.fromEntries(new FormData(e.target));data.archived=e.target.elements.archived.checked;if(cloud())await mutate('/api/teachers'+(id?'/'+id:''),id?'PATCH':'POST',{...data,...(id?{revision:t.revision}:{})});else{const {validPhoneList}=await import('./core.mjs');if(!validPhoneList(data.phone))throw Error('Enter a valid international phone number.');const next={...t,...data,id:id||crypto.randomUUID()};local.teachers=id?local.teachers.map(v=>v.id===id?next:v):[...local.teachers,next];persistLocal()}try{await resolveScheduleAssignments()}catch(e){bridge.toast('Contact saved. Use Match pending assignments in Teachers to retry matching.')}$('#workspaceDialog').close();bridge.render()})}}
 function teacherImporter(){
  showModal(openAccess?'Import shared teacher contacts':'Import private teacher contacts',`<div class="form-stack"><p>Upload a CSV file or paste the name and phone columns from Excel / Google Sheets. Include country codes. Up to 100 teachers per import.</p><p class="notice">${cloud()?(openAccess?'Contacts will be visible to everyone in the open workspace.':'Contacts will save to your private cloud workspace.'):'Contacts will save on this device. Sign in through Cloud setup first to save across devices.'}</p><label class="field">CSV or text file<input id="teacherImportFile" type="file" accept=".csv,.tsv,.txt,text/csv,text/tab-separated-values,text/plain"></label><label class="field">Names and phone numbers<textarea id="teacherImportText" rows="7" maxlength="200000" placeholder="name,phone"></textarea></label><p class="muted">Two columns: name, phone. A header is optional. Existing contacts are preserved; exact duplicates are skipped.</p><div class="button-row"><button class="secondary" id="teacherImportTemplate">Download CSV template</button><button class="primary" id="teacherImportPreview">Preview contacts</button></div><div id="teacherImportResults" aria-live="polite"></div><button class="primary" id="teacherImportSave" disabled>Import contacts</button><p id="teacherImportError" role="alert"></p></div>`);
  const input=$('#teacherImportText'),file=$('#teacherImportFile'),preview=$('#teacherImportPreview'),save=$('#teacherImportSave'),results=$('#teacherImportResults'),errorBox=$('#teacherImportError'),dialog=$('#workspaceDialog'),close=$('#closeWorkspace');let reviewed=null,busy=false;
  const invalidate=()=>{reviewed=null;save.disabled=true;results.textContent='';errorBox.textContent='';};input.oninput=invalidate;
  $('#teacherImportTemplate').onclick=()=>bridge.download(new Blob(['name,phone\r\n'],{type:'text/csv;charset=utf-8'}),'teacher-contacts-template.csv');
  file.onchange=async()=>{invalidate();try{if(!file.files?.length)return;const f=file.files[0];if(f.size>200000)throw Error('Use a text file smaller than 200 KB.');input.value=await f.text();}catch(e){errorBox.textContent=e.message}};
  const review=()=>{reviewed=parseTeacherImport(input.value,currentTeachers());results.innerHTML=`<p><strong>${reviewed.ready.length} ready</strong> · ${reviewed.duplicates.length} duplicates skipped · ${reviewed.errors.length} need correction</p><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Name</th><th>Phone</th><th>Check</th></tr></thead><tbody>${reviewed.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.phone)}</td><td>${esc(r.reason)}</td></tr>`).join('')}</tbody></table></div>`;save.textContent=`Import ${reviewed.ready.length} contacts`;save.disabled=!reviewed.ready.length||!!reviewed.errors.length;};
  preview.onclick=()=>{errorBox.textContent='';try{review()}catch(e){invalidate();errorBox.textContent=e.message}};
  const preventCancel=e=>{if(busy)e.preventDefault()};dialog.addEventListener('cancel',preventCancel);dialog.addEventListener('close',()=>dialog.removeEventListener('cancel',preventCancel),{once:true});
  save.onclick=async()=>{if(!reviewed||busy)return;let imported=0;const targetCloud=cloud();busy=true;for(const el of [input,file,preview,save,close])el.disabled=true;errorBox.textContent='';
   try{if(targetCloud){await flush();await pull(true);}const fresh=parseTeacherImport(input.value,currentTeachers());if(fresh.errors.length)throw Error('Correct the highlighted rows, then preview again.');for(const row of fresh.ready){save.textContent=`Importing ${imported+1} / ${fresh.ready.length}…`;const data={name:row.name,phone:row.phone,email:'',notes:'',archived:false};if(targetCloud){const result=await request('/api/teachers','POST',data);teachers.push(result.data);}else{local.teachers.push({...data,id:crypto.randomUUID()});persistLocal();}imported++;}try{await resolveScheduleAssignments()}catch{}if(targetCloud)await pull(true);dialog.close();bridge.render();bridge.toast(`${imported} teacher contacts imported${targetCloud?' to cloud.':' on this device.'}`);
   }catch(e){if(targetCloud)try{await pull(true)}catch{}review();errorBox.textContent=`${imported} saved. ${e.message} Preview again before retrying; saved contacts will be skipped.`;}
   finally{busy=false;for(const el of [input,file,preview,close])el.disabled=false;if(dialog.open&&reviewed)save.disabled=!reviewed.ready.length||!!reviewed.errors.length;}
  };
 }
 function reportsView(){return`<div class="workspace"><div class="section-top"><div><h2 class="section-title">የጉባኤ ሪፖርቶች</h2><p class="section-subtitle">ከእያንዳንዱ አስተባባሪ የሚሰጥ የተሳትፎ፣ የትምህርት ግምገማ እና የአስተያየት ሪፖርት።</p></div></div><div class="setup">${cloud()?'':'<p class="notice">ሪፖርቶች በዚህ መሣሪያ ላይ ብቻ ይቀመጣሉ። በሁሉም መሣሪያዎች ለማግኘት ከጋራ ማከማቻው ጋር ይገናኙ።</p>'}<p>ሪፖርት ማስገባት በዱባይ ሰዓት ጉባኤው በሚካሄድበት ቀን ይጀምራል። የእያንዳንዱ አስተባባሪ ማገናኛ ለአንድ ጉባኤ ሪፖርት ብቻ ያገለግላል፤ ከጉባኤው ቀን 45 ቀናት በኋላ ጊዜው ያበቃል።</p></div>${bridge.meetings().sort((a,b)=>a.date.localeCompare(b.date)).map(m=>{const r=currentReports().find(r=>(r.meetingId||r.id)===m.id);return`<div class="report-row"><div><h3 lang="am">${esc(m.topic)}</h3><small>${reportDate(m.date)} · ${r?'ተልኳል · '+esc(reportStatusAm(r.status)):m.date>dubaiDate()?'ጊዜው አልደረሰም':'ሪፖርት አልተላከም'}</small></div><div class="button-row"><button class="secondary" data-report-edit="${m.id}" ${m.date>dubaiDate()?'disabled':''}>${r?'ሪፖርቱን ያስተካክሉ':'ሪፖርት ያስገቡ'}</button>${cloud()?`<button class="prepare" data-report-link="${m.id}">የአስተባባሪ ማገናኛ ↗</button>`:''}</div></div>`}).join('')}</div>`}
 function editReport(id){const m=bridge.meetings().find(m=>m.id===id),r=currentReports().find(r=>(r.meetingId||r.id)===id)||{};showModal('የጉባኤ ሪፖርት',`<h2 lang="am" class="detail-title">${esc(m.topic)}</h2><p>${reportDate(m.date)}</p><form class="form-stack" id="reportForm" lang="am" novalidate>${reportFields(r,currentTeachers().find(t=>t.id===assignment(id))?.name||m.scheduledTeacherName||'')}<button class="primary">ሪፖርቱን ያስቀምጡ</button><p role="alert" id="formError"></p></form>`);bindReportFields($('#reportForm'));$('#reportForm').onsubmit=e=>{e.preventDefault();submitForm(e.target,async()=>{if(m.date>dubaiDate())throw Error('ሪፖርት ማስገባት ጉባኤው በሚካሄድበት ቀን ይጀምራል።');const data=readReport(e.target,r.assignedTeacherName||currentTeachers().find(t=>t.id===assignment(id))?.name||m.scheduledTeacherName||'',r);if(cloud())await mutate('/api/meetings/'+id+'/report','PUT',{...data,revision:r.revision||0});else{const record={...data,id,meetingId:id,updatedAt:new Date().toISOString()};local.reports=[...local.reports.filter(v=>v.meetingId!==id),record];local.outcomes={...local.outcomes,[id]:{outcome:'held',outcomeReason:''}};persistLocal();loadLocalPrograms()}$('#workspaceDialog').close();bridge.render();bridge.toast('ሪፖርቱ ተቀምጧል።')})}}
 function monthlyView(){const range=custom?{from,to}:{month};let report;try{report=monthlyReport(bridge.meetings(),currentReports(),range,dubaiDate(),currentTeachers())}catch{}return`<div class="workspace"><div class="section-top"><div><h2 class="section-title">Monthly service report</h2><p class="section-subtitle">Dashboard and detailed table for the selected monthly program.</p></div></div><div class="setup report-setup">${renderGate()}<div class="button-row"><label class="field">Month<input id="reportMonth" type="month" value="${month}"></label><button class="secondary" id="fullProgram">Full program</button><button class="secondary" id="customRange">${custom?'Use month':'Custom dates'}</button></div>${custom?`<div class="button-row">${field('From','from',from,'date')}${field('Through','to',to,'date')}</div>`:''}${report?`<p class="muted">${prettyDate(report.from)} – ${prettyDate(report.to)} · Dubai time</p><div class="button-row"><button class="primary" id="exportReport">Download CSV</button><button class="secondary" id="printReport">Print dashboard & table / Save PDF</button></div>`:'<p class="bad">Choose valid dates (up to one year).</p>'}</div>${report?`<div id="printArea"><h2 class="print-only">Gubae monthly report · ${esc(report.from)} – ${esc(report.to)}</h2>${reportDashboard(report)}${reportTable(report)}</div>`:''}</div>`}
 function reportDashboard(report){const s=report.summary;const metrics=[['Total gubae',s.scheduled],['Held',s.held],['Missed / not held',s.missed],['Total participants',s.totalParticipants],['Missing reports',s.missing],['Teacher replacements',s.teacherReplacements],['Assigned teacher did not teach',s.assignedDidNotTeach],['Upcoming',s.upcoming]];return`<section class="report-dashboard" aria-label="Monthly report dashboard"><h3>Month at a glance</h3><div class="report-summary">${metrics.map(([label,value])=>`<article><span>${label}</span><strong>${value}</strong></article>`).join('')}</div><p class="muted">Missed includes reported missed, cancelled and postponed gubaes. Missing reports have no organizer report; status can still be set from All meetings. Total participants counts attendances across gubaes, not unique people.</p><div class="dashboard-panels"><section class="dashboard-panel"><h3>Gubae outcomes</h3>${[['Held',s.held,'held'],['Missed / not held',s.missed,'missed'],['Missing report',s.missing,'unconfirmed'],['Upcoming',s.upcoming,'upcoming']].map(([label,count,kind])=>`<div class="outcome-row"><span>${label}</span><strong>${count}</strong><div class="outcome-track"><span class="${kind}" style="width:${s.scheduled?Math.round(count/s.scheduled*100):0}%"></span></div></div>`).join('')}<p class="muted">Average participants per held gubae: ${s.averageParticipants??'—'} · Average teaching rating: ${s.averageTeachingRating??'—'}/5</p></section><section class="dashboard-panel"><h3>Why gubaes were missed</h3>${report.missedReasons.length?`<ul class="missed-reasons">${report.missedReasons.map(r=>`<li><span>${esc(r.reason)}</span><strong>${r.count}</strong></li>`).join('')}</ul>`:'<p class="muted">No gubaes reported as missed in this period.</p>'}<p class="muted">${s.cancelled} cancelled · ${s.postponed} postponed</p></section></div><section class="dashboard-panel teacher-coverage"><h3>Assigned teachers who did not teach</h3><p class="muted">Reported replacements and absences only. Teacher attendance is unknown for ${s.teacherNotRecorded} held gubae(s).</p>${report.teacherChanges.length?`<div class="report-table-wrap"><table class="report-table teacher-change-table"><thead><tr><th>Assigned teacher</th><th>Who taught instead?</th><th>Gubae / date</th><th>Reason</th></tr></thead><tbody>${report.teacherChanges.map(v=>`<tr><td>${esc(v.assignedTeacherName)}</td><td>${esc(v.actualTeacherName||'No replacement taught')}</td><td><strong lang="am">${esc(v.topic)}</strong><small>${esc(v.date)}</small></td><td>${esc(v.report.teacherChangeReason||'Reason not recorded')}</td></tr>`).join('')}</tbody></table></div>`:'<p>No teacher replacements or absences have been reported in this period.</p>'}</section></section>`}
 function reportTable(r){return`<section class="report-detail"><h3>Detailed gubae report</h3><div class="report-table-wrap"><table class="report-table monthly-detail-table"><thead><tr><th>Gubae / date</th><th>Outcome / report</th><th>Participants</th><th>Why not held?</th><th>Assigned teacher</th><th>Who taught?</th><th>Teacher change / reason</th><th>Teaching feedback</th><th>Comments</th></tr></thead><tbody>${r.rows.map(v=>`<tr><td><strong lang="am">${esc(v.topic)}</strong><small>${esc(v.date)}</small>${v.report?`<small>Organizer: ${esc(v.report.organizerName)}</small>`:''}</td><td>${esc(meetingStatusLabel(v.status))}${v.report?'<small>Report submitted</small>':''}</td><td>${v.status==='held'?v.report?.participants??'Not reported':'—'}</td><td>${['missed','cancelled','postponed'].includes(v.status)?esc(v.missedReason||'Reason not recorded'):'—'}</td><td>${esc(v.assignedTeacherName)}</td><td>${esc(v.actualTeacherName||(v.report?.teacherOutcome==='not_taught'?'No replacement':'Not recorded'))}</td><td>${esc(teacherOutcomeLabel(v.report?.teacherOutcome))}<p>${esc(v.report?.teacherChangeReason)}</p></td><td>${v.report?.teachingRating??'—'}<p>${esc(v.report?.teachingFeedback)}</p></td><td>${esc(v.report?.comments)}</td></tr>`).join('')||'<tr><td colspan="9">No gubaes in this period.</td></tr>'}</tbody></table></div></section>`}
 function emailReminderView(){return `<section class="setup email-reminders"><h3>Email reminder list</h3><p>One reminder at 9 AM Dubai time on days with announcements due. Everyone on this list receives the same link and can help send on WhatsApp.</p><form id="emailReminderForm"><label class="field">Reminder recipients<textarea id="reminderRecipients" rows="4" placeholder="name@example.com, helper@example.com">${esc(reminderSettings.recipients.join('\n'))}</textarea></label><label><input type="checkbox" id="reminderEnabled" ${reminderSettings.enabled?'checked':''}> Enable daily email reminders</label><div class="button-row"><button class="primary" type="submit">Save reminder list</button><a class="secondary" href="due.html" target="_blank" rel="noopener noreferrer">Open due-only page ↗</a></div><p id="reminderListResult" role="status"></p></form><p class="muted">Add up to 50 addresses, separated by commas, semicolons or new lines. Sent announcements disappear from the shared due list. WhatsApp still requires the final Send action.</p></section>`;}
 function setupView(){return `<section class="cloud-setup setup"><h3>Shared workspace</h3><p>${openAccess?'No account is required. Everyone who opens this site can view and edit the shared data, including contacts and reports.':'Use the same administrator Google account on your phone and PC. Cloud records are accessible only after sign-in.'}</p><label class="field">Render backend URL<input type="url" id="apiBase" value="${esc(apiBase)}" placeholder="https://your-service.onrender.com"></label><div class="button-row"><button class="primary" id="connectBackend">Connect backend</button>${auth?`<button class="secondary" id="signIn">${user?'Sign out':'Sign in with Google'}</button>`:''}${cloud()?'<button class="secondary" id="refreshCloud">Refresh cloud</button><button class="secondary" id="migrateLocal">Import this device’s original setup</button><button class="secondary" id="cloudBackup">Export cloud records</button>':''}</div><p class="muted">${apiBase?'Cloud connection configured.':'Backend has not been deployed yet. The app currently saves on this device.'} Original posters are shared with all devices; custom poster replacements remain on the device where you attach them. Sending still finishes in WhatsApp.</p></section>`}
 function showModal(title,html){$('#workspaceDialogTitle').textContent=title;$('#workspaceDialogBody').innerHTML=html;$('#workspaceDialog').showModal()}
 async function submitForm(form,fn){const button=form.querySelector('button[type="submit"],button.primary');button.disabled=true;try{await fn()}catch(e){$('#formError').textContent=form.id==='reportForm'?reportErrorAm(e):e.message}finally{button.disabled=false}}
 function bind(){$('#emailReminderForm')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const recipients=reminderEmails($('#reminderRecipients').value);const result=await mutate('/api/reminders/config','PUT',{revision:reminderSettings.revision||0,recipients,enabled:$('#reminderEnabled').checked});reminderSettings=result;bridge.render();$('#reminderListResult').textContent='Reminder email list saved.';}catch(error){$('#reminderListResult').textContent=error.message;}finally{button.disabled=false;}});
 $('#newTeacher')?.addEventListener('click',()=>teacherEditor());$('#importTeachers')?.addEventListener('click',()=>teacherImporter());document.querySelectorAll('[data-add-scheduled-teacher]').forEach(b=>b.onclick=()=>teacherEditor(undefined,{name:b.dataset.addScheduledTeacher}));document.querySelectorAll('[data-resolve-scheduled]').forEach(b=>b.onclick=()=>action(async()=>{b.disabled=true;try{await resolveScheduleAssignments();bridge.render();bridge.toast('Teacher matching refreshed.')}finally{b.disabled=false}}));document.querySelectorAll('[data-teacher-edit]').forEach(b=>b.onclick=()=>teacherEditor(b.dataset.teacherEdit));
 document.querySelectorAll('[data-assignment]').forEach(b=>b.onchange=()=>action(async()=>{const id=b.dataset.assignment;if(cloud()){await flush();const m=records.find(m=>m.id===id);await mutate('/api/meetings/'+id,'PATCH',{revision:m.revision,teacherId:b.value||null})}else{local.assignments[id]=b.value;persistLocal();bridge.render()}}));
 document.querySelectorAll('[data-teacher-send]').forEach(b=>b.onclick=()=>action(async()=>{const m=bridge.meetings().find(m=>m.id===b.dataset.teacherSend),t=currentTeachers().find(t=>t.id===assignment(m.id)),phones=phoneList(t.phone);if(phones.length===1)window.open(waUrl(phones[0],message(m)),'_blank','noopener,noreferrer');else showModal('Choose teacher’s number',`<p>Select the intended private chat.</p>${phones.map(p=>`<p><a target="_blank" rel="noopener noreferrer" href="${esc(waUrl(p,message(m)))}">${esc(p)} ↗</a></p>`).join('')}`)}));
 document.querySelectorAll('[data-teacher-status]').forEach(b=>b.onclick=()=>action(async()=>{const id=b.dataset.teacherStatus;if(cloud()){await flush();const m=records.find(m=>m.id===id);await mutate(`/api/meetings/${id}/status/teacher`,'PUT',{revision:m.revision,sent:!m.sent?.teacher})}else{local.teacherSent[id]=!local.teacherSent[id];persistLocal();bridge.render()}}));
 document.querySelectorAll('[data-outcome]').forEach(b=>b.onclick=()=>editOutcome(b.dataset.outcome));
 document.querySelectorAll('[data-report-edit]').forEach(b=>b.onclick=()=>editReport(b.dataset.reportEdit));
 document.querySelectorAll('[data-report-link]').forEach(b=>b.onclick=()=>{const id=b.dataset.reportLink;showModal('የአስተባባሪ ሪፖርት ማገናኛ',`<p>አዲስ ማገናኛ ሲፈጠር የዚህን ጉባኤ የቀድሞ ማገናኛ ይተካል። ማገናኛውን የያዘ ሰው ይህን ሪፖርት ብቻ ማየት እና ማስተካከል ይችላል።</p><div class="button-row"><button class="primary" id="generateLink">ማገናኛ ይፍጠሩ / ይተኩ</button><button class="secondary" id="revokeLink">ማገናኛውን ያሰናክሉ</button></div><div id="linkResult"></div>`);$('#generateLink').onclick=()=>action(async()=>{const result=await mutate('/api/meetings/'+id+'/report-link','POST',{});result.url=reportPageUrl(result.url);$('#linkResult').innerHTML=`<p>የሚያበቃበት ቀን፦ ${esc(result.expiresAt.slice(0,10))}</p><label class="field">የአስተባባሪ ማገናኛ<input readonly id="organizerLink" value="${esc(result.url)}"></label><button class="secondary" id="copyOrganizer">የአስተባባሪውን ማገናኛ ይቅዱ</button>`;$('#copyOrganizer').onclick=()=>action(async()=>{await copy(result.url);bridge.toast('የአስተባባሪው ማገናኛ ተቀድቷል።')})});$('#revokeLink').onclick=()=>action(async()=>{await mutate('/api/meetings/'+id+'/report-link','DELETE');$('#linkResult').textContent='የአስተባባሪው ማገናኛ ተሰናክሏል።'})});
 $('#reportMonth')?.addEventListener('change',e=>{month=e.target.value;custom=false;bridge.render()});$('#fullProgram')?.addEventListener('click',()=>{const dates=bridge.meetings().map(m=>m.date).sort();from=dates[0];to=dates.at(-1);custom=true;bridge.render()});$('#customRange')?.addEventListener('click',()=>{if(!from){const r=dateRange({month});from=r.from;to=r.to}custom=!custom;bridge.render()});for(const name of ['from','to'])document.querySelector(`.report-setup [name="${name}"]`)?.addEventListener('change',e=>{if(name==='from')from=e.target.value;else to=e.target.value;bridge.render()});
 $('#exportReport')?.addEventListener('click',()=>{const report=monthlyReport(bridge.meetings(),currentReports(),custom?{from,to}:{month},dubaiDate(),currentTeachers());bridge.download(new Blob([reportCsv(report)],{type:'text/csv;charset=utf-8'}),`gubae-report-${report.from}-${report.to}.csv`)});$('#printReport')?.addEventListener('click',()=>window.print());
 $('#connectBackend')?.addEventListener('click',()=>action(async()=>{const url=new URL($('#apiBase').value);if(url.protocol!=='https:'&&url.hostname!=='localhost')throw Error('Use an HTTPS backend URL.');localStorage.setItem('gubae-api-base',url.origin);location.reload()}));$('#signIn')?.addEventListener('click',()=>action(async()=>{if(user){if(pending)await flush();await auth.signOut();location.reload()}else await auth.signIn()}));$('#refreshCloud')?.addEventListener('click',()=>action(async()=>{await flush();await pull(true)}));$('#migrateLocal')?.addEventListener('click',()=>action(async()=>{const data=JSON.parse(localStorage.getItem('gubae-announcements-v1')||'{}');const result=await mutate('/api/import','POST',{format:'gubae-v1',...data});bridge.toast(result.message)}));$('#cloudBackup')?.addEventListener('click',()=>action(async()=>{await flush();const result=await request('/api/state');bridge.download(new Blob([JSON.stringify({format:'gubae-cloud-v2',exportedAt:new Date().toISOString(),...result.data})],{type:'application/json'}),'gubae-cloud-backup-'+dubaiDate()+'.json')}));
 }
 function afterRender(){drawPrograms();const container=$('#content');if(cloud()&&['recipients','settings'].includes(bridge.view()))container.insertAdjacentHTML('beforeend',emailReminderView());if(bridge.view()==='settings'){container.insertAdjacentHTML('afterbegin',setupView());if(cloud()){container.querySelector('.setup:not(.cloud-setup)')?.insertAdjacentHTML('afterbegin','<div class="notice">Cloud mode is active. Recipients, edits, sent status, teacher contacts, and reports sync through the backend. Export cloud records above for a complete cloud snapshot.</div>')}}if(cloud()){for(const el of container.querySelectorAll('.notice,.muted,.section-subtitle,.field-hint')){el.innerHTML=el.innerHTML.replaceAll('Numbers are stored only in this browser.',(openAccess?'Numbers are shared with everyone who opens this site.':'Numbers sync to your private cloud workspace.')).replaceAll('This site does not synchronize between devices.','Cloud records sync after confirmed saves.').replaceAll('A simple frontend workspace, with your setup saved on your device.','Your workspace, connected across devices.')}}bind()}
 async function start(){
 const bar=document.createElement('div');bar.className='sync-bar';bar.innerHTML='<span id="syncText" role="status">On this device · cloud not connected</span><div class="button-row"><button class="secondary" id="retrySync">Retry sync</button><button class="secondary" id="discardSync">Discard pending / refresh</button><button class="secondary" id="openSetup">Cloud setup</button></div>';document.querySelector('header').after(bar);const programBar=document.createElement('div');programBar.id='programBar';programBar.className='program-bar';bar.after(programBar);$('#openSetup').onclick=()=>bridge.navigate('settings');$('#retrySync').onclick=()=>action(async()=>{syncError='';await flush();await pull(true)});$('#discardSync').onclick=()=>action(async()=>{if(!cloud())return;pending=null;syncError='';await pull(true)});
 window.addEventListener('beforeunload',e=>{if(pending||syncing){e.preventDefault();e.returnValue=''}});
 const dialog=document.createElement('dialog');dialog.id='workspaceDialog';dialog.innerHTML='<div class="dialog-top"><span id="workspaceDialogTitle"></span><button class="icon-button" id="closeWorkspace" aria-label="Close form">×</button></div><div id="workspaceDialogBody"></div>';document.body.append(dialog);$('#closeWorkspace').onclick=()=>dialog.close();
 if(new URLSearchParams(location.search).has('report')){await organizerPage();return}loadLocalPrograms(false);drawPrograms();
 try{const config=await fetch('./cloud-config.json').then(r=>r.json());apiBase=localStorage.getItem('gubae-api-base')||config.apiBase||'';if(apiBase){const url=new URL(apiBase);if(url.protocol!=='https:'&&url.hostname!=='localhost')throw Error('The backend URL must use HTTPS.');apiBase=url.origin;notice('Connecting to shared workspace…');const r=await fetch(apiBase+'/api/config');if(!r.ok)throw Error('Backend configuration could not load.');const cfg=await r.json();openAccess=cfg.accessMode==='public';if(openAccess){mode='connecting';const result=await request('/api/state');records=result.data.meetings;teachers=result.data.teachers;reports=result.data.reports;programs=result.data.programs||[];reminderSettings=result.data.reminderSettings||{recipients:[],enabled:false,revision:0};etag=result.tag;mode='cloud';applyRecords();notice('Open workspace · synced');}else{const {connectAuth}=await import('./firebase-auth.mjs');auth=await connectAuth(cfg.firebase,async next=>{user=next;if(user){mode='connecting';notice('Loading shared records…');try{const result=await request('/api/state');records=result.data.meetings;teachers=result.data.teachers;reports=result.data.reports;programs=result.data.programs||[];reminderSettings=result.data.reminderSettings||{recipients:[],enabled:false,revision:0};etag=result.tag;mode='cloud';applyRecords();notice(openAccess?'Open workspace · synced':'Cloud synced · '+user.email)}catch(e){mode='local';bridge.restoreLocal();loadLocalPrograms();notice('Cloud sign-in failed · using this device');error(e)}}else{mode='local';bridge.restoreLocal();loadLocalPrograms();notice('On this device · sign in for cloud sync')}bridge.render()});}setInterval(()=>pull(),60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)pull()})}else ensureProgram()}catch(e){ensureProgram();notice('Cloud unavailable · using this device');error(e)}bridge.render()
 }
 async function organizerPage(){location.replace(reportPageUrl(location.href));}

 async function importBackup(data){if(!cloud())return false;const result=await mutate('/api/import','POST',data);bridge.toast(result.message+' Custom poster attachments remain local.');return true}
 return{publicAccess:()=>openAccess,reports:currentReports,importBackup,persist,afterRender,render:v=>v==='teachers'?teachersView():v==='reports'?reportsView():v==='monthly'?monthlyView():null,start,cloud,flush};
}
